<div class="settings-section appearance-section">
    <h2>Appearance</h2>

    <div class="form-group">
        <label>Theme</label>
        <div class="radio-group">
            @foreach (var theme in _themes)
            {
                <label class="radio-item">
                    <input type="radio" name="theme" value="@theme"
                           checked="@(_theme == theme)"
                           @onchange="() => _theme = theme" />
                    <span>@theme</span>
                </label>
            }
        </div>
    </div>

    <div class="form-group">
        <label>Font Size</label>
        <div class="radio-group">
            @foreach (var size in _fontSizes)
            {
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="@size"
                           checked="@(_fontSize == size)"
                           @onchange="() => _fontSize = size" />
                    <span>@size</span>
                </label>
            }
        </div>
    </div>

    <div class="form-group">
        <label for="language">Language</label>
        <select id="language" @bind="_language">
            @foreach (var lang in _languages)
            {
                <option value="@lang">@lang</option>
            }
        </select>
    </div>

    <div class="form-group">
        <label class="toggle-item">
            <input type="checkbox" checked="@_compactMode" @onchange="e => _compactMode = (bool)e.Value!" />
            <span>Compact Mode</span>
        </label>
    </div>

    <div class="preview-area" style="@GetPreviewStyle()">
        <h4>Live Preview</h4>
        <p>This is how your content will look with the selected settings.</p>
        <p>The quick brown fox jumps over the lazy dog.</p>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private static readonly string[] _themes = { "Light", "Dark", "System" };
    private static readonly string[] _fontSizes = { "Small", "Medium", "Large" };
    private static readonly string[] _languages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    protected override void OnParametersSet()
    {
        if (Settings is not null)
        {
            _theme = Settings.Theme;
            _fontSize = Settings.FontSize;
            _language = Settings.Language;
            _compactMode = Settings.CompactMode;
        }
    }

    private string GetPreviewStyle()
    {
        var bg = _theme switch
        {
            "Dark" => "background:#1e1e1e; color:#e0e0e0;",
            "Light" => "background:#ffffff; color:#333333;",
            _ => "background:#f5f5f5; color:#333333;"
        };

        var font = _fontSize switch
        {
            "Small" => "font-size:0.85rem;",
            "Large" => "font-size:1.25rem;",
            _ => "font-size:1rem;"
        };

        var padding = _compactMode ? "padding:0.5rem;" : "padding:1.5rem;";

        return $"{bg} {font} {padding} border-radius:8px; border:1px solid #ccc; margin:1rem 0;";
    }

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await OnSave.InvokeAsync(updated);
    }
}

