@namespace sv_ea6e6a2351b84324a0b959ecac8dd8e2.Components.Pages.Settings
@using sv_ea6e6a2351b84324a0b959ecac8dd8e2.Services

<div class="settings-section notifications-section">
    <h2>Notifications</h2>

    <div class="toggle-group">
        <label class="toggle-item">
            <input type="checkbox" checked="@_emailNotifications" @onchange="e => _emailNotifications = (bool)e.Value!" />
            <span>Email Notifications</span>
        </label>

        <label class="toggle-item">
            <input type="checkbox" checked="@_pushNotifications" @onchange="e => _pushNotifications = (bool)e.Value!" />
            <span>Push Notifications</span>
        </label>

        <label class="toggle-item">
            <input type="checkbox" checked="@_weeklyDigest" @onchange="e => _weeklyDigest = (bool)e.Value!" />
            <span>Weekly Digest</span>
        </label>
    </div>

    <h3>Muted Channels</h3>
    <div class="channel-list">
        @foreach (var channel in _allChannels)
        {
            <label class="channel-item">
                <input type="checkbox"
                       checked="@_mutedChannels.Contains(channel)"
                       @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                <span>@channel</span>
            </label>
        }
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync">Save Preferences</button>
    </div>
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();

    private static readonly string[] _allChannels = { "general", "marketing", "engineering", "design", "announcements" };

    protected override void OnParametersSet()
    {
        if (Prefs is not null)
        {
            _emailNotifications = Prefs.EmailNotifications;
            _pushNotifications = Prefs.PushNotifications;
            _weeklyDigest = Prefs.WeeklyDigest;
            _mutedChannels = new HashSet<string>(Prefs.MutedChannels);
        }
    }

    private void ToggleMute(string channel, bool isMuted)
    {
        if (isMuted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
    }
}

